import pathlib,urllib.request,urllib.error,json
p=pathlib.Path('/home/appontrack/public_html/.htaccess')
old=p.read_text()
anchor='RewriteRule ^saas/console/?(.*)$ /$1 [L,QSA]'
assert anchor in old,'unexpected_rewrite_baseline'
if 'RewriteRule ^saas/console/login/?$' not in old:
 patched=old.replace(anchor,'RewriteCond %{REQUEST_METHOD} ^(GET|HEAD)$\nRewriteRule ^saas/console/login/?$ /login [R=302,L]\n'+anchor,1)
 p.write_text(patched);p.chmod(0o644)
def probe():
 req=urllib.request.Request('https://app.ontrackegy.com/saas/console/login',headers={'Cache-Control':'no-cache','User-Agent':'OnTrack-Legacy-Login-Probe'})
 try:
  with urllib.request.urlopen(req,timeout=7) as response:return (response.status,response.url.endswith('/login'))
 except urllib.error.HTTPError as e:return(e.code,False)
try:
 code,mapped=probe()
 if code!=200 or not mapped:raise RuntimeError('legacy_login_redirect_failed')
 print(json.dumps({'status':'legacy_login_redirect_verified','http':code,'canonical_url':'/login','previous_admin_root_untouched':True}))
except Exception:
 p.write_text(old)
 raise
